package com.learnspherex.payment;
import java.math.*; import java.time.*; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="installments",uniqueConstraints=@UniqueConstraint(columnNames={"fee_plan_id","installment_number"})) @Getter @NoArgsConstructor @EqualsAndHashCode(of="id") public class Installment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="fee_plan_id",nullable=false) private FeePlan feePlan; @Column(name="installment_number",nullable=false) private int installmentNumber; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Column(nullable=false) private LocalDate dueDate; public Installment(FeePlan f,int n,BigDecimal a,LocalDate d){feePlan=f;installmentNumber=n;amount=a;dueDate=d;} }
